-- ==============================================================
-- V2: ADD FIELD/STATUS/TAGS COLUMNS & SEED 406 DUT REGULATIONS
-- ==============================================================

ALTER TABLE regulations ADD COLUMN IF NOT EXISTS document_id VARCHAR(50);
ALTER TABLE regulations ADD COLUMN IF NOT EXISTS field VARCHAR(255);
ALTER TABLE regulations ADD COLUMN IF NOT EXISTS status VARCHAR(100);
ALTER TABLE regulations ADD COLUMN IF NOT EXISTS tags TEXT;

CREATE INDEX IF NOT EXISTS idx_regulations_category ON regulations(category);
CREATE INDEX IF NOT EXISTS idx_regulations_doc_number ON regulations(document_number);
CREATE UNIQUE INDEX IF NOT EXISTS uq_regulations_document_id ON regulations(document_id) WHERE document_id IS NOT NULL;

-- Enrich existing V1 seed rows with tags/field/status
UPDATE regulations SET field = 'Công tác sinh viên', status = 'Còn hiệu lực',
  tags = '["Công tác sinh viên","Học bổng","Còn hiệu lực"]'
WHERE document_number IN ('1414/QĐ-ĐHBK', '28/VBHN-BGDĐT', '35/2011/TT-BGDĐT') AND tags IS NULL;

